Rules.InvariantScript:
Refresh(CostCodes);
ClearCollect(colCostCodes, CostCodes);
Set(varSubmitAsEmail, User().Email);
Set(varSubmitAsName, User().FullName);
Set(
    varApprovers,
    LookUp(colEmployeesAll, Lower(Email_Address) = Lower(User().Email))
);
Set(varApprover1Email, varApprovers.'Approver 1 Email');
Set(SelectedProject, Trim(Coalesce(varApprovers.'Project Title', "")));
Refresh(Public_Holidays);
ClearCollect(
    colPublic_Holidays,
    AddColumns(
        Public_Holidays,
        CleanDate,
        DateValue(Trim(Text(Date))) + 1,
        CleanDateKey,
        Text(DateValue(Trim(Text(Date))) + 1, "yyyy-mm-dd")
    )
);
If(
    IsBlank(varSelectedCostCode),
    Set(varSelectedCostCode, First(Sort(Distinct(colCostCodes, Network_Activity_Name), Value)).Value);
    Set(
        varSelectedCostCodeID,
        LookUp(colCostCodes, Network_Activity_Name = varSelectedCostCode).Network_Activity
    )
);
If(
    IsBlank(varCurrentWeekStart),
    Set(
        varCurrentWeekStart,
        DateAdd(Today(), -(Weekday(Today(), StartOfWeek.Monday) - 1), "Days")
    )
);
Select(Button_LoadWeek);

Set(varSelectedCostCode, Self.Selected.Value);
Set(varSelectedCostCodeID, LookUp(colCostCodes, Network_Activity_Name = Self.Selected.Value).Network_Activity);
Select(Button_LoadWeek);

If(
    varIsSaving,
    Notify("Please wait, saving in progress...", NotificationType.Warning),
    CountIf(
        colHoursGallery,
        Or(
            And(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), !IsBlank(StandardHours)),
            And(TaskCode <> "Work Day", TaskCode <> "Weekend", !IsBlank(TaskCode))
        ) &&
        ApprovalStatus <> "Approved"
    ) = 0,
    Notify("No hours to save", NotificationType.Warning),
    CountIf(
        colHoursGallery,
        !IsBlank(StandardHours) &&
        (TaskCode = "Work Day" || IsBlank(TaskCode)) &&
        IsBlank(CostCode) &&
        ApprovalStatus <> "Approved"
    ) > 0,
    Notify("Work Day entries must have a cost code", NotificationType.Error),
    Set(varIsSaving, true);
    ClearCollect(
        HoursDraftNew,
        Filter(
            colHoursGallery,
            (
                (Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)) && !IsBlank(StandardHours)) ||
                (TaskCode <> "Work Day" && TaskCode <> "Weekend" && !IsBlank(TaskCode))
            ) &&
            RecordID = 0 &&
            IsDirty = true &&
            ApprovalStatus <> "Approved"
        )
    );
    ForAll(
        HoursDraftNew,
        With(
            { logID: Text(GUID()) },
            Patch(
                'Hours Tracking (Hours)',
                Defaults('Hours Tracking (Hours)'),
                {
                    Title: logID,
                    LOG_ID: logID,
                    Employee_Name: varSubmitAsName,
                    Employee: varSubmitAsEmail,
                    Cost_code: CostCode,
                    Date: WorkDate,
                    Standard_time: If(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), Value(Coalesce(StandardHours, "0")), 0),
                    Task: Coalesce(TaskCode, "Work Day"),
                    Comments: Comments,
                    App_Name: "Staffclock",
                    ApproverID_1: varApprover1Email,
                    ApprovalStatus_1: "Draft"
                }
            )
        )
    );
    ClearCollect(
        HoursDraftUpdate,
        Filter(
            colHoursGallery,
            (
                (Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)) && !IsBlank(StandardHours)) ||
                (TaskCode <> "Work Day" && TaskCode <> "Weekend" && !IsBlank(TaskCode))
            ) &&
            RecordID <> 0 &&
            ApprovalStatus <> "Approved" &&
            IsDirty = true
        )
    );
    ForAll(
        HoursDraftUpdate,
        Patch(
            'Hours Tracking (Hours)',
            LookUp('Hours Tracking (Hours)', ID = RecordID),
            {
                Cost_code: CostCode,
                Standard_time: If(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), Value(Coalesce(StandardHours, "0")), 0),
                Task: Coalesce(TaskCode, "Work Day"),
                Comments: Comments,
                ApprovalStatus_1: If(ApprovalStatus = "Draft", "Draft", ApprovalStatus)
            }
        )
    );
    If(
        varFirstTimeUser,
        Patch(
            'Hours Tracking (Active Users)',
            Defaults('Hours Tracking (Active Users)'),
            {
                Title: User().Email,
                Name: User().FullName
            }
        );
        Set(varFirstTimeUser, false)
    );
    Notify("Saved as Draft", NotificationType.Success);
    Refresh('Hours Tracking (Hours)');
    Clear(HoursDraftNew);
    Clear(HoursDraftUpdate);
    Set(varIsSaving, false);
    Select(Button_LoadWeek)
)

UpdateIf(
    colHoursGallery,
    RowKey = ThisItem.RowKey,
    {
        CostCode: Self.Selected.Value,
        CostCodeID: LookUp(colCostCodes, Network_Activity_Name = Self.Selected.Value).Network_Activity,
        IsDirty: true
    }
)

UpdateIf(
    colHoursGallery,
    RowKey = ThisItem.RowKey,
    {
        TaskCode: Self.Selected.Value,
        IsDirty: true
    }
)

UpdateIf(
    colHoursGallery,
    RowKey = ThisItem.RowKey,
    {
        StandardHours: Self.Text,
        IsDirty: true
    }
)

UpdateIf(
    colHoursGallery,
    RowKey = ThisItem.RowKey,
    {
        Comments: Self.Text,
        IsDirty: true
    }
)

If(
    ThisItem.RecordID <> 0,
    Remove(
        'Hours Tracking (Hours)',
        LookUp('Hours Tracking (Hours)', ID = ThisItem.RecordID)
    )
);
Remove(colHoursGallery, ThisItem)

If(
    varIsSaving,
    Notify("Please wait, saving in progress...", NotificationType.Warning),
    CountIf(
        colHoursGallery,
        Or(
            And(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), !IsBlank(StandardHours)),
            And(TaskCode <> "Work Day", TaskCode <> "Weekend", !IsBlank(TaskCode))
        ) &&
        ApprovalStatus <> "Approved"
    ) = 0,
    Notify("No hours to submit", NotificationType.Warning),
    CountIf(
        colHoursGallery,
        !IsBlank(StandardHours) &&
        (TaskCode = "Work Day" || IsBlank(TaskCode)) &&
        IsBlank(CostCode) &&
        ApprovalStatus <> "Approved"
    ) > 0,
    Notify("Work Day entries must have a cost code", NotificationType.Error),
    Set(varIsSaving, true);
    ClearCollect(
        HoursNewCollection,
        Filter(
            colHoursGallery,
            (
                (Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)) && !IsBlank(StandardHours)) ||
                (TaskCode <> "Work Day" && TaskCode <> "Weekend" && !IsBlank(TaskCode))
            ) &&
            RecordID = 0 &&
            ApprovalStatus <> "Approved"
        )
    );
    ForAll(
        HoursNewCollection,
        With(
            { logID: Text(GUID()) },
            Patch(
                'Hours Tracking (Hours)',
                Defaults('Hours Tracking (Hours)'),
                {
                    Title: logID,
                    LOG_ID: logID,
                    Employee_Name: varSubmitAsName,
                    Employee: varSubmitAsEmail,
                    Cost_code: CostCode,
                    Date: WorkDate,
                    Standard_time: If(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), Value(Coalesce(StandardHours, "0")), 0),
                    Task: Coalesce(TaskCode, "Work Day"),
                    Comments: Comments,
                    App_Name: "Staffclock",
                    ApproverID_1: varApprover1Email,
                    ApprovalStatus_1: If(IsBlank(varApprover1Email), "Approved", "Pending")
                }
            )
        )
    );
    ClearCollect(
        HoursDraftCollection,
        Filter(
            colHoursGallery,
            (
                (Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)) && !IsBlank(StandardHours)) ||
                (TaskCode <> "Work Day" && TaskCode <> "Weekend" && !IsBlank(TaskCode))
            ) &&
            RecordID <> 0 &&
            ApprovalStatus <> "Approved"
        )
    );
    ForAll(
        HoursDraftCollection,
        Patch(
            'Hours Tracking (Hours)',
            LookUp('Hours Tracking (Hours)', ID = RecordID),
            {
                Cost_code: CostCode,
                Standard_time: If(Or(TaskCode = "Work Day", TaskCode = "Weekend", IsBlank(TaskCode)), Value(Coalesce(StandardHours, "0")), 0),
                Task: Coalesce(TaskCode, "Work Day"),
                Comments: Comments,
                ApprovalStatus_1: If(IsBlank(varApprover1Email), "Approved", "Pending")
            }
        )
    );
    If(
        varFirstTimeUser,
        Patch(
            'Hours Tracking (Active Users)',
            Defaults('Hours Tracking (Active Users)'),
            {
                Title: User().Email,
                Name: User().FullName
            }
        );
        Set(varFirstTimeUser, false)
    );
    Notify("Hours Submitted", NotificationType.Success);
    Refresh('Hours Tracking (Hours)');
    Clear(HoursNewCollection);
    Clear(HoursDraftCollection);
    Set(varIsSaving, false);
    Select(Button_LoadWeek)
)
